/* ── DOM: header player, end card and first-visit popup ─── */
const KEY='mc_classroom_trailer_v1';
function readState(){try{const v=JSON.parse(localStorage.getItem(KEY)||'null');return v&&typeof v==='object'?v:{};}catch{return {};}}
