 setState('idle');
 let lastPct=-1;
 player.on('time',T=>{const pct=Math.round(T/DURATION*1000)/10;if(pct!==lastPct){lastPct=pct;fill.style.transform=`scaleX(${T/DURATION})`;time.textContent=fmt(T);track.setAttribute('aria-valuenow',String(Math.floor(T)));}});
