 H.burst(ctx,T,7,{x:g.bx,y:g.by,count:320,seed:703,speed:s.u*92,life:1.3,gravity:s.u*38,size:s.u*.55,colors:[PAL.hot,PAL.gold,PAL.cream,'#f0b44c']});
