 for(let j=0;j<6;j++){const q=((j+T*.9)%6)/6,yy=fy+D*q*q;ctx.globalAlpha=.22*inK*st*q;ctx.beginPath();ctx.moveTo(0,yy);ctx.lineTo(s.w,yy);ctx.stroke();}
