 if(T>=18.6&&T<19.3){const q=prog(18.6,19.3,T);for(let i=0;i<4;i++)H.glow(ctx,wx+(i-1.5)*wr*.25+Math.sin(T*3+i)*K*2,wy-ry-q*wr*.6-i*K*2,K*(5+q*6),PAL.cream,.12*(1-q));}
