 H.rr(ctx,bx,by,w,bh,br);ctx.lineWidth=Math.max(1.5,S*.018);ctx.strokeStyle='rgba(255,255,255,.6)';ctx.stroke();
 ctx.fillStyle='rgba(255,255,255,.2)';H.rr(ctx,bx+w*.1,by+bh*.12,w*.07,bh*.58,w*.035);ctx.fill();
