 for(let i=0;i<90;i++){const x=r()*304,w=3+r()*22,y=8+r()*20,h=2+r()*9,k=r();t.fillStyle=k<.45?'rgba(244,236,216,.95)':k<.75?'rgba(242,160,123,.95)':'rgba(226,194,122,.9)';t.fillRect(x,y,w,h);}
