  // ▶ at the right end: pulses scale 1→1.06 on every beat
  const pb=1+.06*beatBump(T,52.5,8)*(T>=52.8?1:0),ts=G.size*.3*pb;
  ctx.globalAlpha=capA*clamp((draw-.6)/.4);
